# Stage 5 copy run for issue 255. The run sheet is docs/security/issue-255-stage5-evidence.md.
# Usage: scripts/issue-255-copy-run-wizard.sh [--from STAGE_NUMBER]
# Cookies and hosts stay in a mode-700 folder in $HOME. The last stage deletes it and keeps only the results.

COMMIT=11660b02fef74b3dcaf16aeb10ceffd0c77c1ace
BUNDLE_SHA_PREFIX=d8b24294
REPO=Jahazel/lsat-scheduler
REPO_ROOT=$(git rev-parse --show-toplevel)
PT_SCREENSHOT="$REPO_ROOT/src/lib/practiceTestFixtures/pt158-s1.png"
OFF_TEXT="Scanning is off right now. Enter your analytics by hand."
RUN_DIR="$HOME/.drillmap-stage5-run"
RESULTS_KEPT="$HOME/drillmap-stage5-results.md"
umask 077
mkdir -p "$RUN_DIR"
chmod 700 "$RUN_DIR"
ENV_FILE="$RUN_DIR/values.env"
RESULTS="$RUN_DIR/results.md"
if [[ -f "$ENV_FILE" ]]; then set -a; . "$ENV_FILE"; set +a; fi

MONTH_START="date_trunc('month', now() AT TIME ZONE 'America/Chicago') AT TIME ZONE 'America/Chicago'"
TOTAL_SQL="SELECT total_usd, warning_sent_at IS NOT NULL AS warned, limit_alert_sent_at IS NOT NULL AS limit_alerted
FROM scan_spending WHERE month_start = $MONTH_START;"

record() {
  [[ -f "$RESULTS" ]] || printf '| Step | Result |\n| --- | --- |\n' > "$RESULTS"
  printf '| %s | %s |\n' "$1" "$2" >> "$RESULTS"
  printf '  %s✓ recorded%s %s: %s\n' "$GREEN" "$RESET" "$1" "$2"
}

# ask_result STEP "Prompt" records what the owner saw. Never type an email, cookie, or URL here.
ask_result() {
  local answer=""
  read -e -r -p "  $BOLD$2$RESET " answer || true
  record "$1" "$answer"
}

show_sql() {
  printf '\n'
  printf '%s\n' "$1" | sed 's/^/      /'
  printf '\n'
  if printf '%s' "$1" | pbcopy 2>/dev/null; then note "Copied to the clipboard. Paste it in Neon's SQL Editor on the copy project."; fi
}

# ask_id KEY "Prompt" asks until the answer looks like a Vercel deployment ID.
ask_id() {
  while true; do
    ask "$1" "$2"
    printf -v "$1" '%s' "${!1#dpl_}"
    if [[ "${!1}" =~ ^[A-Za-z0-9]{10,}$ ]]; then printf -v "$1" 'dpl_%s' "${!1}"; return 0; fi
    warn "That is not a deployment ID. Copy only the part after the last / in the deployment's Vercel address."
    printf -v "$1" '%s' ""; write_env "$1" "" > /dev/null
  done
}

# ask_host KEY "Prompt" asks until the answer looks like a domain name.
ask_host() {
  local value
  while true; do
    ask "$1" "$2"
    value="${!1#https://}"; value="${value%%/*}"
    if [[ "$value" =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$ ]]; then printf -v "$1" '%s' "$value"; return 0; fi
    warn "That is not a domain. Copy it from the copy project's Domains list, for example something.vercel.app."
    printf -v "$1" '%s' ""; write_env "$1" "" > /dev/null
  done
}

clear_clipboard() { printf '' | pbcopy 2>/dev/null || true; }

save_cookie() {
  printf 'Cookie: __Secure-authjs.session-token=%s\n' "$2" > "$RUN_DIR/cookie-$1"
}

host_of() { if [[ "$1" == A ]]; then printf '%s' "$COPY_HOST"; else printf '%s' "$B_HOST"; fi; }

# scan_once A|B student|admin analytics|practice OUT starts one scan request and writes OUT.result as "CODE SECONDS".
scan_once() {
  local host path headers fields
  host=$(host_of "$1")
  headers=(-H "@$RUN_DIR/cookie-$2")
  if [[ "$1" == B && -f "$RUN_DIR/bypass" ]]; then headers+=(-H "@$RUN_DIR/bypass"); fi
  if [[ "$3" == analytics ]]; then
    path=/api/analytics/extract; fields=(-F "image=@$LR_SCREENSHOT" -F section=LR)
  else
    path=/api/practice-test/extract; fields=(-F "image=@$PT_SCREENSHOT")
  fi
  curl -sS --max-time 120 -o "$4.body" -D "$4.headers" -w '%{http_code} %{time_total}\n' \
    "${headers[@]}" "${fields[@]}" "https://$host$path" > "$4.result" 2>/dev/null || true
  [[ -s "$4.result" ]] || printf '000 0\n' > "$4.result"
}

describe_scan() {
  local code seconds reason retry
  read -r code seconds < "$1.result"
  reason=$(sed -n 's/.*"reason":"\([a-z-]*\)".*/\1/p' "$1.body" 2>/dev/null || true)
  retry=$(grep -i '^retry-after:' "$1.headers" 2>/dev/null | tr -d '\r' | awk '{print $2}' || true)
  printf 'HTTP %s in %ss%s%s' "$code" "$seconds" "${reason:+, reason $reason}" "${retry:+, Retry-After $retry}"
}

# scan STEP A|B who kind runs one scan and records its status.
scan() {
  local out="$RUN_DIR/scan-$1"
  say "Sending one $4 scan as the $3 to deployment $2…"
  scan_once "$2" "$3" "$4" "$out"
  LAST_SCAN=$(describe_scan "$out")
  LAST_CODE=$(cut -d' ' -f1 < "$out.result")
  record "$1" "$LAST_SCAN"
  if [[ "$LAST_CODE" == 429 ]] && grep -qF "$OFF_TEXT" "$out.body"; then note "The reply says: $OFF_TEXT"; fi
}

# scan_burst STEP kind A:who B:who ... sends every scan at the same moment and records the tally.
scan_burst() {
  local step="$1" kind="$2" dir="$RUN_DIR/burst-$1" i=0 pair summary
  shift 2
  rm -rf "$dir"; mkdir -p "$dir"
  for pair in "$@"; do
    i=$((i + 1))
    scan_once "${pair%%:*}" "${pair##*:}" "$kind" "$dir/$i" &
  done
  wait
  summary=""
  for ((n = 1; n <= i; n++)); do summary+="#$n ${*:n:1}: $(describe_scan "$dir/$n"); "; done
  local refused ran
  refused=$(cat "$dir"/*.result | grep -c '^429' || true)
  ran=$((i - refused))
  record "$step" "$i sent at once: $ran ran, $refused refused (429). ${summary%; }"
}

# capture_curl NAME A|B reads a "Copy as cURL" request from the clipboard into the run folder.
capture_curl() {
  local file="$RUN_DIR/$1.curl" host
  host=$(host_of "$2")
  while true; do
    pause "When the request is copied as cURL, press Enter"
    pbpaste > "$file"
    clear_clipboard
    if ! head -c 4 "$file" | grep -q '^curl'; then warn "The clipboard does not start with curl. Copy the request again."; continue; fi
    if ! grep -qF "https://$host" "$file"; then warn "That request is not for deployment $2 ($host). Copy the right one."; continue; fi
    if ! grep -qi 'next-action' "$file"; then warn "That request has no Next-Action header. Copy the POST request of the form."; continue; fi
    note "Saved. The clipboard is cleared because the request holds your cookie."
    return 0
  done
}

replay_once() {
  local command
  command="$(cat "$1") -sS --max-time 60 -o $(printf '%q' "$2.body") -w '%{http_code}\n'"
  bash -c "$command" > "$2.result" 2>/dev/null || true
  [[ -s "$2.result" ]] || printf '000\n' > "$2.result"
}

# replay_burst STEP "refusal text" sends 5 replays of A.curl and 5 of B.curl at the same moment.
replay_burst() {
  local step="$1" refusal="$2" a="$3" b="$4" dir="$RUN_DIR/burst-$1" i
  rm -rf "$dir"; mkdir -p "$dir"
  for i in 1 2 3 4 5; do replay_once "$a" "$dir/a$i" & replay_once "$b" "$dir/b$i" & done
  wait
  local refused codes
  refused=$(grep -lF "$refusal" "$dir"/*.body 2>/dev/null | wc -l | tr -d ' ')
  codes=$(cat "$dir"/*.result | sort | uniq -c | awk '{printf "%s×%s ", $1, $2}')
  record "$step" "10 sent at once (5 to A, 5 to B): $refused carry the refusal text, $((10 - refused)) do not. HTTP codes: ${codes% }"
}

s_version() {
  stage "Check the version"
  git -C "$REPO_ROOT" fetch -q origin main
  local main bundle
  main=$(git -C "$REPO_ROOT" rev-parse origin/main)
  say "Run sheet commit: $COMMIT"
  say "origin/main now:  $main"
  if [[ "$main" != "$COMMIT" ]]; then warn "main moved. Stop and ask the agent to update the run sheet before you go on."; pause "Press Enter to continue anyway, or Ctrl-C to stop"; fi
  if ! git -C "$REPO_ROOT" diff --quiet "$COMMIT" HEAD -- migrations sql scripts/sql-editor-migrations.mjs scripts/migrationBundle.mjs src; then
    warn "This checkout's code differs from the run sheet commit. Stop and ask the agent."
    pause "Press Enter to continue anyway, or Ctrl-C to stop"
  fi
  bundle=$(cd "$REPO_ROOT" && node scripts/sql-editor-migrations.mjs | shasum -a 256 | cut -c1-8)
  record "A1 commit" "origin/main $(printf '%.7s' "$main"), bundle hash starts $bundle (expected $BUNDLE_SHA_PREFIX)"
  open_url "https://vercel.com/dashboard"
  step "Open the REAL site's Vercel project. Copy the ID of its current Production deployment (starts dpl_)."
  ask_id REAL_DEPLOYMENT_BEFORE "Real site Production deployment ID:"
  write_env REAL_DEPLOYMENT_BEFORE "$REAL_DEPLOYMENT_BEFORE"
  record "A1 real site before" "$REAL_DEPLOYMENT_BEFORE"
}

