  while true; do
    ask LR_SCREENSHOT "Path to a 7Sage LR analytics screenshot (PNG, JPG, or WebP):"
    LR_SCREENSHOT="${LR_SCREENSHOT//\\/}"; LR_SCREENSHOT="${LR_SCREENSHOT//\'/}"; LR_SCREENSHOT="${LR_SCREENSHOT%"${LR_SCREENSHOT##*[! ]}"}"
    LR_SCREENSHOT="${LR_SCREENSHOT/#\~/$HOME}"
    [[ -f "$LR_SCREENSHOT" ]] && break
    warn "No file at that path. Drag the screenshot from Finder into this window, then press Enter."
  done
  write_env LR_SCREENSHOT "$LR_SCREENSHOT"
  ask_result "A8" "Did onboarding finish on This week with typed analytics? (yes/no and notes)"
}

s_c4_first() {
  stage "C4: first real scans and the month's total"
  show_sql "$TOTAL_SQL"
  ask_result "C4-1 total before" "Month's total before (or 'no row'):"
  scan "C4-2" A student analytics
  show_sql "$TOTAL_SQL"
  ask_result "C4-2 total" "Month's total now:"
  open_url "https://console.anthropic.com/workspaces/default/logs"
  step "In the copy workspace's logs or usage, count the requests for that scan."
  ask_result "C4-2 console" "Requests for that scan, and its cost if shown:"
  scan "C4-3 practice test" A student practice
  show_sql "$TOTAL_SQL"
  ask_result "C4-3 total after practice test" "Month's total now:"
  scan "C4-3 admin" A admin analytics
  show_sql "$TOTAL_SQL"
  ask_result "C4-3 total after admin scan" "Month's total now:"
}

s_deploy_b() {
  stage "C2: make deployment B"
  say "Deployment B is a second Production deployment of the same commit. It runs on its own server instances."
  open_url "https://vercel.com/dashboard"
  step "In the COPY project, open deployment A > ⋯ > Redeploy. Keep Production. Do not promote the result."
  step "When it is Ready, copy its own URL (…vercel.app) and its ID."
  ask_id DEPLOYMENT_B "Deployment B ID (dpl_…):"
  ask_host B_HOST "Deployment B host, without https://:"
  write_env DEPLOYMENT_B "$DEPLOYMENT_B"
  write_env B_HOST "$B_HOST"
  local code
  code=$(curl -s -o /dev/null -w '%{http_code}' "https://$B_HOST/login" || true)
  if [[ "$code" == 401 || "$code" == 403 ]]; then
    warn "B answers HTTP $code: Deployment Protection is on."
    step "COPY project > Settings > Deployment Protection > Protection Bypass for Automation > create a secret."
    local secret=""
    ask_secret secret "Paste the bypass secret (hidden):"
    printf 'x-vercel-protection-bypass: %s\n' "$secret" > "$RUN_DIR/bypass"
    note "In the browser, open https://$B_HOST/?x-vercel-protection-bypass=SECRET&x-vercel-set-bypass-cookie=true once, with your secret, before steps C2-5 and C2-6."
    secret=""
    code=$(curl -s -o /dev/null -w '%{http_code}' -H "@$RUN_DIR/bypass" "https://$B_HOST/login" || true)
  fi
  record "C2-1" "deployment B $DEPLOYMENT_B, /login answers HTTP $code$([[ -f "$RUN_DIR/bypass" ]] && echo ' with the bypass header')"
}

s_c2_one_student() {
  stage "C2: one student, 6 scans at once"
  say "Expected: exactly one runs. Five get 429 still-reading."
  pause "Press Enter to send 3 to A and 3 to B at the same moment"
  scan_burst "C2-2" analytics A:student A:student A:student B:student B:student B:student
  show_sql "SELECT count(*) FROM running_scans;"
  ask_result "C2-2 places after" "Held places now (expected 0):"
}

s_c2_site() {
  stage "C2: the 6th scan on the site"
  say "Four held places come from SQL. The test student (A) and the Admin (B) then race for the 5th."
  show_sql "INSERT INTO running_scans (subject, started_at) SELECT 'stage5-held-' || g, now() FROM generate_series(1, 4) g;"
  warn "Held places free after 2 minutes. Press Enter within 1 minute of running the SQL."
  pause "Press Enter right after INSERT 0 4"
  scan_burst "C2-3" analytics A:student B:admin
  show_sql "DELETE FROM running_scans WHERE subject LIKE 'stage5-held-%';"
  ask_result "C2-3 delete" "What did the DELETE return?"
}

s_c2_stopped() {
  stage "C2: a place held by a stopped scan frees after 2 minutes"
  show_sql "INSERT INTO running_scans (subject, started_at) SELECT id::text, now() - interval '100 seconds' FROM accounts WHERE email = '$TEST_EMAIL';"
  pause "Press Enter right after INSERT 0 1"
  scan "C2-4 first" A student analytics
  local retry
  retry=$(grep -i '^retry-after:' "$RUN_DIR/scan-C2-4 first.headers" 2>/dev/null | tr -d '\r' | awk '{print $2}' || true)
  say "Waiting ${retry:-20} seconds and 2 more…"
  sleep $(( ${retry:-20} + 2 ))
  scan "C2-4 second" A student analytics
}

s_c2_leads() {
  stage "C2: lead capture burst"
  say "First fill the lead limit in the browser, so the copied request is a refused one and saves nothing."
  open_url "https://$COPY_HOST/"
  step "Open DevTools > Network. On the home page email form, submit a test address (not a real person's)."
  step "Submit again until the form says 'Too many tries from this network.'"
  step "Right-click that last POST request > Copy > Copy as cURL."
  capture_curl lead-A A
  open_url "https://$B_HOST/"
  step "On deployment B's home page, submit the same address once. It is refused. Copy that POST as cURL."
  capture_curl lead-B B
  show_sql "DELETE FROM action_counters WHERE action = 'leadCapture';"
  pause "Press Enter right after the DELETE"
  replay_burst "C2-5" "Too many tries from this network" "$RUN_DIR/lead-A.curl" "$RUN_DIR/lead-B.curl"
  show_sql "SELECT sum(count) FROM action_counters WHERE action = 'leadCapture';"
  ask_result "C2-5 counter" "Sum of counts (expected 10):"
  ask LEAD_TEST_EMAIL "The test address you used (for the cleanup SQL only):"
  write_env LEAD_TEST_EMAIL "$LEAD_TEST_EMAIL"
}

s_c2_saves() {
  stage "C2: analytics snapshot save burst (Admin)"
  open_url "https://$COPY_HOST/admin"
  step "As the Admin, open Test controls and set the date to the coming Saturday, so the weekly upload is open."
  step "If the Admin's student side has no onboarding yet, finish it with 'Type your analytics' first."
  pause "Press Enter when the date is set"
  say "Fill the Admin's save counter for today, so the copied requests are refused ones."
  show_sql "INSERT INTO action_counters (action, subject, window_start, window_end, count)
SELECT 'analyticsSnapshotSave', id::text,
  date_trunc('day', now() AT TIME ZONE 'America/Chicago') AT TIME ZONE 'America/Chicago',
  (date_trunc('day', now() AT TIME ZONE 'America/Chicago') + interval '1 day') AT TIME ZONE 'America/Chicago', 5
FROM accounts WHERE email = '$ADMIN_EMAIL'
ON CONFLICT (action, subject, window_start) DO UPDATE SET count = 5;"
  pause "Press Enter after INSERT 0 1"
  open_url "https://$COPY_HOST/dashboard/upload"
  step "DevTools > Network open. Choose 'Type your analytics', fill the values, confirm, and approve."
  step "The page says 'You've saved your analytics 5 times today.' Copy that POST as cURL."
  capture_curl save-A A
  say "Now sign in on deployment B with the Admin's cookie."
  step "Open https://$B_HOST/ . DevTools > Application > Cookies > https://$B_HOST > add __Secure-authjs.session-token with the Admin's value, Secure on."
  step "Open https://$B_HOST/dashboard/upload, type the same analytics, approve, and copy the refused POST as cURL."
  capture_curl save-B B
  show_sql "SELECT count(*) FROM analytics_snapshots s JOIN students st ON st.id = s.student_id JOIN accounts a ON a.id = st.account_id WHERE a.email = '$ADMIN_EMAIL';"
  ask_result "C2-6 snapshots before" "Admin's snapshot count before the burst:"
  show_sql "DELETE FROM action_counters WHERE action = 'analyticsSnapshotSave' AND subject = (SELECT id::text FROM accounts WHERE email = '$ADMIN_EMAIL');"
  pause "Press Enter right after DELETE 1"
  replay_burst "C2-6" "saved your analytics 5 times today" "$RUN_DIR/save-A.curl" "$RUN_DIR/save-B.curl"
  show_sql "SELECT count(*) FROM analytics_snapshots s JOIN students st ON st.id = s.student_id JOIN accounts a ON a.id = st.account_id WHERE a.email = '$ADMIN_EMAIL';"
  ask_result "C2-6 snapshots after" "Admin's snapshot count after (expected before + 5):"
}

s_c4_warning() {
  stage "C4: the 80% warning"
  show_sql "UPDATE scan_settings SET monthly_limit_usd = floor(((SELECT total_usd FROM scan_spending WHERE month_start = $MONTH_START) + 0.02) / 0.8 * 100) / 100;
SELECT s.total_usd + 0.02 <= t.monthly_limit_usd AS fits, s.total_usd + 0.02 >= 0.8 * t.monthly_limit_usd AS warns, t.monthly_limit_usd
FROM scan_spending s, scan_settings t WHERE s.month_start = $MONTH_START;"
  note "Both fits and warns must be true. If fits is false, the total is under \$0.02: tell the agent."
  ask_result "C4-4 setup" "fits, warns, and the new limit:"
  scan "C4-4" A student analytics
  show_sql "$TOTAL_SQL"
  ask_result "C4-4 total" "total_usd and warned:"
  say "Watch your inbox for the 'Copy: app spend at 80%' check going down."
  ask_result "C4-4 email" "Did the 80% email arrive? (yes/no, and the minutes it took)"
}

s_c4_limit() {
  stage "C4: refused at the limit minus \$0.01"
  show_sql "UPDATE scan_settings SET monthly_limit_usd = ceil((SELECT total_usd FROM scan_spending WHERE month_start = $MONTH_START) * 100) / 100 + 0.01;
SELECT monthly_limit_usd FROM scan_settings;"
  ask_result "C4-5 limit" "The new limit:"
  show_sql "$TOTAL_SQL"
  ask_result "C4-5 total before" "total_usd before:"
  scan "C4-5 analytics" A student analytics
  scan "C4-5 practice test" A student practice
  show_sql "$TOTAL_SQL"
  ask_result "C4-5 total after" "total_usd and limit_alerted now (total should not change):"
  step "In the Anthropic Console, check that no new request arrived for these two scans."
  ask_result "C4-5 console" "New requests in the console:"
  ask_result "C4-5 email" "Did the 'limit reached' email arrive, and only once?"
}

s_c4_changed() {
  stage "C4: a changed limit works on the next scan"
  show_sql "UPDATE scan_settings SET monthly_limit_usd = 10;"
  pause "Press Enter after UPDATE 1"
  scan "C4-6" A student analytics
}

s_c4_timeout() {
  stage "C4: the 30-second timeout keeps the count"
  say "For this step only, the copy sends scans to an address that never answers."
  open_url "https://vercel.com/dashboard"
  step "COPY project > Settings > Environment Variables: add ANTHROPIC_BASE_URL = https://10.255.255.1 for Production."
  step "Redeploy deployment A to Production and promote the new deployment."
  ask_id DEPLOYMENT_TIMEOUT "The new deployment's ID:"
  write_env DEPLOYMENT_TIMEOUT "$DEPLOYMENT_TIMEOUT"
  pause "Press Enter when the copy's domain serves it"
  local out="$RUN_DIR/scan-C4-7"
  scan_once A student analytics "$out" &
  local pid=$!
  say "The scan is waiting now. Within 25 seconds, run:"
  show_sql "$TOTAL_SQL
SELECT count(*) FROM running_scans;"
  ask_result "C4-7 during" "total_usd and held places during the wait:"
  wait "$pid" || true
  record "C4-7" "$(describe_scan "$out")"
  grep -qF "Reading took too long" "$out.body" && note "The reply says: Reading took too long and stopped. Try again."
  show_sql "$TOTAL_SQL"
  ask_result "C4-7 after" "total_usd after the reply:"
  step "In the Anthropic Console, check that no request arrived for this scan."
  ask_result "C4-7 console" "Requests in the console:"
  step "Now delete ANTHROPIC_BASE_URL in the COPY project. Redeploy to Production and promote."
  ask_id DEPLOYMENT_RESTORED "The restored deployment's ID:"
  write_env DEPLOYMENT_RESTORED "$DEPLOYMENT_RESTORED"
  record "C4-7 restore" "ANTHROPIC_BASE_URL removed, deployment $DEPLOYMENT_RESTORED promoted"
}

s_c5_switch() {
  stage "C5: the emergency switch"
  show_sql "UPDATE scan_settings SET scanning_off = true;"
  pause "Press Enter after UPDATE 1"
  show_sql "$TOTAL_SQL"
  ask_result "C5-1 total before" "total_usd before:"
  scan "C5-1" A student analytics
  show_sql "$TOTAL_SQL"
  ask_result "C5-1 total after" "total_usd after (should not change):"
  ask_result "C5-1 console" "New requests in the Anthropic Console:"
}

s_c5_pages() {
  stage "C5: hand-typed analytics, This week, and Progress while scanning is off"
  open_url "https://$COPY_HOST/dashboard/upload"
  step "As the Admin (date still on Saturday), open the weekly upload."
  ask_result "C5-2" "Does it say '$OFF_TEXT' with the typed form open?"
  show_sql "DELETE FROM action_counters WHERE action = 'analyticsSnapshotSave' AND subject = (SELECT id::text FROM accounts WHERE email = '$ADMIN_EMAIL');"
  step "Type analytics, confirm they are your latest, and approve."
  show_sql "SELECT extraction_source FROM analytics_snapshots s JOIN students st ON st.id = s.student_id JOIN accounts a ON a.id = st.account_id WHERE a.email = '$ADMIN_EMAIL' ORDER BY s.approved_at DESC LIMIT 1;"
  ask_result "C5-3" "Did it save and open This week? What source did the SQL show?"
  open_url "https://$COPY_HOST/progress"
  ask_result "C5-4" "Do This week and Progress load with data?"
  step "If This week shows a practice test in the coming week, set the date to the Saturday after it,"
  step "open the weekly upload, and approve without the practice-test result. Otherwise answer 'Not run'."
  ask_result "C5-5" "Skip note shown, upload saved, and no 'missed type goes first' next week? (or Not run)"
  show_sql "UPDATE scan_settings SET scanning_off = false;"
  ask_result "C5-6" "What did the UPDATE return?"
}

s_cleanup() {
  stage "Clean up"
  show_sql "SELECT scanning_off, monthly_limit_usd FROM scan_settings;
DELETE FROM leads WHERE email = '$LEAD_TEST_EMAIL';"
  ask_result "Z1" "Settings (expected false, 10.00) and the DELETE result:"
  step "Pause both Healthchecks.io checks again."
  step "Delete the Protection Bypass secret if you made one, and delete deployment B ($DEPLOYMENT_B)."
  step "In Test controls, clear the Admin's test date."
  ask_result "Z2" "Checks paused, bypass removed, B deleted, date cleared?"
  step "On the copy, press 'Sign out of all devices' for the test student and for the Admin."
  ask_result "Z3" "Done for both?"
  open_url "https://vercel.com/dashboard"
  ask_id REAL_DEPLOYMENT_AFTER "Real site Production deployment ID now:"
  record "Z4 real site after" "$REAL_DEPLOYMENT_AFTER (before: $REAL_DEPLOYMENT_BEFORE)"
  cp "$RESULTS" "$RESULTS_KEPT"
  rm -rf "$RUN_DIR"
}

run_wizard() {

local stages=(s_version s_alerts s_anthropic s_migrations s_readback s_deploy_a s_check_copy s_accounts
  s_c4_first s_deploy_b s_c2_one_student s_c2_site s_c2_stopped s_c2_leads s_c2_saves
  s_c4_warning s_c4_limit s_c4_changed s_c4_timeout s_c5_switch s_c5_pages s_cleanup)
TOTAL_STAGES=${#stages[@]}
local from=1
if [[ "${1:-}" == --from ]]; then from="${2:?--from needs a stage number}"; fi

if (( from == 1 )); then banner "DrillMap Stage 5 copy run (issue 255)"; fi
_STAGE_INDEX=$((from - 1))
local i
for ((i = from - 1; i < TOTAL_STAGES; i++)); do "${stages[i]}"; done

finish
say "Results: $RESULTS_KEPT"
say "Send that file's contents to the agent. It holds no email, cookie, or URL secret."
}

run_wizard "$@"; exit
